#!/var/local/bin/dash
# sweet-early.sh: the first thing of ours at boot (ws-tools-state). launchd job org.iosonpixel.sweetearly
# (phone/boot/org.iosonpixel.sweetearly.plist; RunAtLoad, root, Nice -20, added to /System/Library/xpc/launchd.plist
# by tools/launchd-add-job.py). Replaces the hook in sensd-probe.sh, which started sweet-sysctl.sh only after the
# sensdprobe job ran (no order against CommCenter / mediaserverd at all).
#
# 1. /var/local/sweet-sysctl.conf (generated by tools/state.py from [sysctl] in state/redfin.toml): one
#    "NAME VALUE" per line, decimal VALUE, '#' comments. Each value is set with /var/local/bin/sctl and logged as ONE
#    console line (/dev/console -> the kernel log, so a boot log shows it next to the kernel's own lines) plus a line
#    in /var/local/sweet-sysctl.log. The first console line says whether CommCenter / mediaserverd were already
#    running when the values went in, which is what proves (or disproves) the order on a given boot.
#    Off without removing anything: touch /var/local/sweet-sysctl.off
# 2. /var/local/scratch/ is emptied: the one place agents may write by hand; state.py diff ignores it.
#
# launchd has no "before job X" ordering: all RunAtLoad/KeepAlive jobs start together. This job only does ~10 sctl
# calls (tens of ms) and is high priority, so it normally wins against CommCenter's first QMI traffic; the console
# lines say when it did not. The strict alternative is the kernel reading the conf once the root volume is mounted.
export PATH=/var/local/bin:/usr/bin:/bin:/usr/sbin:/sbin
T=/var/local/bin/toybox
C=/var/local/sweet-sysctl.conf L=/var/local/sweet-sysctl.log S=/var/local/bin/sctl
con() {	# one line to the console (kernel log) and to the log file
	echo "sweet-early: $*" > /dev/console 2>/dev/null
	echo "$($T date +%FT%T) $*" >> $L
}
running() {	# NAME -> pid list or "no"
	r=$(/var/local/bin/psx "$1" 2>/dev/null | while read -r pid ppid uid cpu comm; do [ "$comm" = "$1" ] && printf '%s ' "$pid"; done)
	echo "${r:-no}"
}

if [ -f "$C" ] && [ ! -e /var/local/sweet-sysctl.off ]; then
	con "boot: applying $C (CommCenter running: $(running CommCenter); mediaserverd running: $(running mediaserverd))"
	n=0 ok=0
	while read -r name value extra || [ -n "$name" ]; do
		n=$((n + 1))
		case $name in ''|'#'*) continue;; esac
		case $value in '#'*) value=;; esac
		case $extra in ''|'#'*) ;; *) con "line $n skipped (more than NAME VALUE): $name"; continue;; esac
		case $name in *[!a-z0-9_.]*|.*|*.) con "line $n skipped (bad name): $name"; continue;; esac
		v=${value#-}
		case $v in ''|*[!0-9]*) con "line $n skipped (value not decimal): $name"; continue;; esac
		if out=$($S "$name" "$value" 2>&1); then ok=$((ok + 1)); con "set $out"
		else con "FAILED $name $value: $out"; fi
	done < "$C"
	con "boot: $ok of the conf's values applied"
elif [ -e /var/local/sweet-sysctl.off ]; then
	con "boot: sweet-sysctl.off present, no sysctls applied"
fi

if [ -d /var/local/scratch ]; then
	$T rm -rf /var/local/scratch/* /var/local/scratch/.[!.]* 2>/dev/null
	con "boot: /var/local/scratch emptied"
else
	$T mkdir -p /var/local/scratch
fi
exit 0
